KG42.register("rules-daa46021f20ef3c20bfe0887",{"id":"24-brooklyn_microgrid::v141-c-R006","paper":"24-brooklyn_microgrid","record":{"rule_id":"v141-c-R006","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"For the illustrative simple EMTS, purchasing energy on the microgrid market is conditioned on the local market price falling below its maximum price limit. Scope: Illustrative simple EMTS purchasing on a microgrid market; not a universal BMG trading rule. Condition: The microgrid market price falls below the simple EMTS's maximum price limit. Local trading is conducted only virtually on the blockchain and does not influence the physical delivery of electricity. Scope: BMG local trading on the virtual market layer. Automatic trading requires participant preferences, such as preferred energy sources and price limits. Scope: BMG trading performed automatically by the EMTS. Condition: Automatic trading by the EMTS. The EMTS must have access to its market participant's blockchain account to facilitate energy transactions automatically. Scope: Automatic facilitation of energy transactions by an EMTS using a participant's blockchain account. Condition: Energy transactions are facilitated automatically by the EMTS.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade","pricing.local"],"E":[{"edge_id":"v141-c-R006-E001","source":"execution.energy_trade","target":"pricing.local","type":"conditional_on","constraint_ids":["v141-c-R006-C001"],"evidence_ids":["v141-b-g02-e06"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Automatic facilitation of energy transactions by an EMTS using a participant's blockchain account. | BMG local trading on the virtual market layer. | BMG trading performed automatically by the EMTS. | Illustrative simple EMTS purchasing on a microgrid market; not a universal BMG trading rule.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e06","v141-b-g02-e22","v141-b-g02-e34","v141-b-g03-e023"]},"x":[{"variable_id":"x_R006_buy","symbol":"b","meaning":"Binary purchase-execution decision of the simple EMTS on the microgrid market; b=1 denotes that the simple EMTS executes a purchase at the activation decision.","kind":"operational","domain":"{0,1}","unit":null,"indices":[],"evidence_ids":["v141-b-g02-e06"]}],"theta":[{"parameter_id":"theta_R006_p_local","symbol":"p_{\\mathrm{local}}","meaning":"Local microgrid market price at the activation decision, referred to in the source as the microgrid market price or 'the price'.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e06"]},{"parameter_id":"theta_R006_p_max","symbol":"p_{\\max}","meaning":"Maximum price limit of the simple EMTS, described by the source as 'its maximum price limit'; a participant-specific preference threshold.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e06"]}],"phi":[{"constraint_id":"v141-c-R006-C001","kind":"logical","role":"core","statement":"For the illustrative simple EMTS, purchasing energy on the microgrid market is conditioned on the local market price falling below its maximum price limit. Scope: Illustrative simple EMTS purchasing on a microgrid market; not a universal BMG trading rule. Condition: The microgrid market price falls below the simple EMTS's maximum price limit.","expression":"p_{\\mathrm{local}} \u003c p_{\\max} \\;\\Rightarrow\\; b = 1","formalization_origin":"source","template_id":null,"members":["execution.energy_trade","pricing.local"],"variable_refs":["x_R006_buy"],"parameter_refs":["theta_R006_p_local","theta_R006_p_max"],"evidence_ids":["v141-b-g02-e06"]},{"constraint_id":"v141-c-R006-C002","kind":"procedural","role":"core","statement":"Local trading is conducted only virtually on the blockchain and does not influence the physical delivery of electricity. Scope: BMG local trading on the virtual market layer.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-e023"]},{"constraint_id":"v141-c-R006-C003","kind":"procedural","role":"core","statement":"Automatic trading requires participant preferences, such as preferred energy sources and price limits. Scope: BMG trading performed automatically by the EMTS. Condition: Automatic trading by the EMTS.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e22"]},{"constraint_id":"v141-c-R006-C004","kind":"procedural","role":"core","statement":"The EMTS must have access to its market participant's blockchain account to facilitate energy transactions automatically. Scope: Automatic facilitation of energy transactions by an EMTS using a participant's blockchain account. Condition: Energy transactions are facilitated automatically by the EMTS.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e34"]}],"pi":[{"evidence_id":"v141-b-g02-e06","location":{"location_id":"src-d1d75d8eed-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"3.6 Energy management trading system (EMTS) (C6)","anchor_text":"The EMTS’s main objective is to automatically secure the energy supply for a market participant whil","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"The EMTS’s main objective is to automatically secure the energy supply for a market participant while implementing a specific bidding strategy. The EMTS needs access to the (real time) demand and supply data of its market participant. Based on this data the EMTS forecasts consumption and generation, and develops its bidding strategy accordingly. Furthermore, it trades the predicted amounts on the market platform and may react to variable prices via demand side management [53]. Self-interested rational market participants maximize their revenue and minimize their energy costs. A simple EMTS would always buy energy at the microgrid market when the price falls below its maximum price limit. However, individual agents’ intelligent bidding strategies shall employ varying prices at different times and are one of the core components of active local markets."},{"evidence_id":"v141-b-g02-e22","location":{"location_id":"src-d1d75d8eed-p07-c2r3__v141-a-M01-coordination","page":7,"printed_page":null,"section":"4.2 Market mechanism","anchor_text":"g pp y g ensured without the traditional grid. The BMG’s market mechanism is implemented on the Tran","equation_id":null,"figure_id":"Fig. 6","table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"The BMG’s market mechanism is implemented on the TransActive Grid private blockchain protocol (C3). Thus, the characteristics of data consistency, security, and verification are covered by the TransActive Grid platform and are inherited traits from the blockchain protocol. Based on measurements of demand and supply as well as market information, the platform tracks and displays local (near) real time energy prices on an intuitive interface. Thus, market participants may gather generation, consumption and market information, and trade energy needs accordingly. Trading is mostly done automatically by the EMTS (C6) and just requires several preferences of its market participants, e.g. the preferred energy sources and price limits."},{"evidence_id":"v141-b-g02-e34","location":{"location_id":"src-d1d75d8eed-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"3.6 Energy management trading system (EMTS) (C6)","anchor_text":"The EMTS’s main objective is to automatically secure the energy supply for a market participant whil","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"Socio-economic factors should also be considered by the EMTS (e.g. preferred buying from local renewable generation). As EMTS take over the energy management and decrease the burden of energy trading, they simultaneously increase the social acceptance of the community energy market [26]. The EMTS need to have access to their market participant’s blockchain account to automatically facilitate energy transactions."},{"evidence_id":"v141-b-g03-e023","location":{"location_id":"src-d1d75d8eed-p08-c2r4__v141-a-M01-coordination","page":8,"printed_page":null,"section":"4.2 Market mechanism","anchor_text":"evel topology of the BMG. out trading is only conducted virtually, i.e. conducted on the block- ook ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"Any local trading is only conducted virtually, i.e. conducted on the blockchain. It has no influence on the physical delivery of electricity."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-coordination","v141-a-M01-settlement"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e06","quote":"A simple EMTS would always buy energy at the microgrid market when the price falls below its maximum price limit."}],[{"evidence_id":"v141-b-g03-e023","quote":"Any local trading is only conducted virtually, i.e. conducted on the blockchain. It has no influence on the physical delivery of electricity."}],[{"evidence_id":"v141-b-g02-e22","quote":"Trading is mostly done automatically by the EMTS (C6) and just requires several preferences of its market participants, e.g. the preferred energy sources and price limits."}],[{"evidence_id":"v141-b-g02-e34","quote":"The EMTS need to have access to their market participant’s blockchain account to automatically facilitate energy transactions."}]],"C2_formalization":{"graph_sha256":"76d50f83a4b342ecf2f69e0ef18122c9c29429a884f9c8b298486870971f9467","applicability":"formalized","reason":"Provisional C.2 formalization. C001 has a directly source-supported conditional purchase rule, formalized with local notation for the simple EMTS's purchase action, the local market price, and its maximum price limit. C002-C004 are procedural/virtual-layer, preference, and account-access requirements without quantitative expressions and remain not_formalized. B evidence remains UNREVIEWED; this output does not claim independent source-audit or scientific acceptance.","bindings":[{"object_id":"x_R006_buy","node_ids":["execution.energy_trade"],"edge_ids":["v141-c-R006-E001"],"rationale":"The binary variable represents the simple EMTS's energy-purchase execution, which the frozen graph anchors at execution.energy_trade and relates to pricing.local through the conditional_on edge E001."},{"object_id":"theta_R006_p_local","node_ids":["pricing.local"],"edge_ids":["v141-c-R006-E001"],"rationale":"The local market price is the pricing signal on pricing.local that supplies the condition in C001's conditional_on edge E001."},{"object_id":"theta_R006_p_max","node_ids":["execution.energy_trade","pricing.local"],"edge_ids":["v141-c-R006-E001"],"rationale":"The maximum price limit is the participant-preference threshold used by the execution decision and compared against the local market price on E001."},{"object_id":"v141-c-R006-C001","node_ids":["execution.energy_trade","pricing.local"],"edge_ids":["v141-c-R006-E001"],"rationale":"C001 formalizes the frozen conditional_on relation E001: if the local price is below the simple EMTS's maximum price limit, the purchase action is executed. The implication preserves the source's 'would always buy ... when' condition without asserting behavior above the threshold."},{"object_id":"v141-c-R006-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"C002 is a procedural scope statement about virtual blockchain trading and physical delivery; it attaches to the execution node without a separate frozen edge."},{"object_id":"v141-c-R006-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"C003 is a procedural requirement that automatic trading depends on participant preferences; it attaches to the execution node without a separate frozen edge."},{"object_id":"v141-c-R006-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"C004 is a procedural account-access requirement for automatic transaction facilitation; it attaches to the execution node without a separate frozen edge."}],"revision_requests":[]}},"quarantined_references":[]}});
